// Diagrams deployed without a <bpmndi:BPMNDiagram> (written by hand or generated by code) import
// fine but bpmn-js draws nothing: shapes come only from DI. importXml lays such a process out with
// bpmn.io's bpmn-auto-layout before drawing it. The module is loaded on first need only.
// A diagram whose shapes have DI but some flows don't (a hand-edited file) would drop those flows
// silently too; importXml draws them as straight/elbow edges between their shapes instead.
window.fleansAutoLayout = {
    _moduleUrl: 'https://cdn.jsdelivr.net/npm/bpmn-auto-layout@1.3.0/+esm',

    /** Imports `xml` into a bpmn-js Viewer/Modeler, laying it out first when it has no diagram. */
    importXml: async function (bpmnJs, xml) {
        // importXML rejects a diagram-less file ("no diagram to display"), so check it first, parsed
        // with the instance's own moddle (it carries the fleans:/zeebe: extensions).
        var moddle = bpmnJs.get('moddle');
        var definitions = (await moddle.fromXML(xml, 'bpmn:Definitions')).rootElement;
        if (!definitions.diagrams || !definitions.diagrams.length) {
            // The layout walks incoming/outgoing, which a hand-written process often leaves out
            // (the engine only needs sourceRef/targetRef), so derive them from the flows first.
            this._linkFlows(definitions.rootElements || []);
            var layoutProcess = (await import(this._moduleUrl)).layoutProcess;
            xml = await layoutProcess((await moddle.toXML(definitions)).xml);
        } else if (this._addMissingEdges(moddle, definitions)) {
            xml = (await moddle.toXML(definitions)).xml;
        }
        await bpmnJs.importXML(xml);
    },

    /** Adds a BPMNEdge for every flow/association whose ends are drawn but which has none. */
    _addMissingEdges: function (moddle, definitions) {
        var shapes = {}, edged = {}, diIds = {};
        definitions.diagrams.forEach(function (diagram) {
            (diagram.plane.planeElement || []).forEach(function (di) {
                diIds[di.id] = true;
                if (!di.bpmnElement) return;
                if (di.$type === 'bpmndi:BPMNShape') shapes[di.bpmnElement.id] = { bounds: di.bounds, plane: diagram.plane };
                else if (di.$type === 'bpmndi:BPMNEdge') edged[di.bpmnElement.id] = true;
            });
        });

        var added = [];
        this._connections(definitions.rootElements || []).forEach(function (flow) {
            var source = flow.sourceRef && shapes[flow.sourceRef.id];
            var target = flow.targetRef && shapes[flow.targetRef.id];
            if (edged[flow.id] || !source || !target) return;
            var id = flow.id + '_di';
            while (diIds[id]) id += '_';
            diIds[id] = true;
            source.plane.get('planeElement').push(moddle.create('bpmndi:BPMNEdge', {
                id: id,
                bpmnElement: flow,
                waypoint: this._waypoints(source.bounds, target.bounds).map(function (p) {
                    return moddle.create('dc:Point', p);
                })
            }));
            added.push(flow.id);
        }, this);

        if (added.length) console.warn('BPMN diagram has no edge for ' + added.join(', ') + '; drawing a default one.');
        return added.length > 0;
    },

    // Sequence flows and associations at any depth, plus a collaboration's message flows.
    _connections: function (elements) {
        var self = this, result = [];
        elements.forEach(function (element) {
            (element.flowElements || []).concat(element.artifacts || [], element.messageFlows || []).forEach(function (child) {
                if (child.$type === 'bpmn:SequenceFlow' || child.$type === 'bpmn:Association' || child.$type === 'bpmn:MessageFlow') result.push(child);
            });
            result = result.concat(self._connections((element.flowElements || []).filter(function (c) { return c.flowElements; })));
        });
        return result;
    },

    // Leaves the side of `a` facing `b` (horizontal or vertical, whichever gap is larger) and enters
    // `b` on the opposite side, with an elbow at the midpoint when the two aren't aligned.
    _waypoints: function (a, b) {
        var ac = { x: a.x + a.width / 2, y: a.y + a.height / 2 };
        var bc = { x: b.x + b.width / 2, y: b.y + b.height / 2 };
        var dx = bc.x - ac.x, dy = bc.y - ac.y;
        if (Math.abs(dx) >= Math.abs(dy)) {
            var sx = dx >= 0 ? a.x + a.width : a.x, tx = dx >= 0 ? b.x : b.x + b.width;
            if (ac.y === bc.y) return [{ x: sx, y: ac.y }, { x: tx, y: bc.y }];
            var mx = Math.round((sx + tx) / 2);
            return [{ x: sx, y: ac.y }, { x: mx, y: ac.y }, { x: mx, y: bc.y }, { x: tx, y: bc.y }];
        }
        var sy = dy >= 0 ? a.y + a.height : a.y, ty = dy >= 0 ? b.y : b.y + b.height;
        if (ac.x === bc.x) return [{ x: ac.x, y: sy }, { x: bc.x, y: ty }];
        var my = Math.round((sy + ty) / 2);
        return [{ x: ac.x, y: sy }, { x: ac.x, y: my }, { x: bc.x, y: my }, { x: bc.x, y: ty }];
    },

    _linkFlows: function (elements) {
        var self = this;
        elements.forEach(function (element) {
            var children = element.flowElements || [];
            children.forEach(function (flow) {
                if (flow.$type !== 'bpmn:SequenceFlow' || !flow.sourceRef || !flow.targetRef) return;
                var outgoing = flow.sourceRef.get('outgoing');
                var incoming = flow.targetRef.get('incoming');
                if (outgoing.indexOf(flow) === -1) outgoing.push(flow);
                if (incoming.indexOf(flow) === -1) incoming.push(flow);
            });
            self._linkFlows(children.filter(function (c) { return c.flowElements; }));
        });
    }
};
